export const ADAMS_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/adams-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getAdamsStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(ADAMS_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
